// https://openprocessing.org/sketch/2018712
// inspired by house in Vancouver

const sze = 50;
let num, cells;

function setup() {
	num = floor(max(windowWidth, windowHeight) / sze);
	const WH = num * sze;
	createCanvas(WH, WH);
	describe("unregular grid with some   combined cells with different colorful background and inner simple shapes")
	// pixelDensity(1);
	randomSeed(random(day()+hour()+minute()+second()))
	initCells();
	joinCells(num);
}

function initCells() {
	cells = [];
	for (let yi = 0; yi < num; yi++) {
		for (let xi = 0; xi < num; xi++) {
			cells.push(new Cell(xi, yi, sze))
		}
	}
}
function joinCells(n = 1, tries = 10) {
	for (let i = 0; i < n; i++) {
		for (let j = 0; j < tries; j++) {
			const c = random(cells)
			const s = floor(sqrt(random(num)+1));
			if (c.expand(s, cells, num)) break; // expand random cell	
		}
	}
}

function mousePressed() {
	if (mouseButton === LEFT) {
		setup();
		joinCells();
		draw();
	}
}

function draw() {
	background(255);
	for (let c of cells) c.show();
	addGrain();
	// noLoop() removed for animation
}

function addGrain() {
	push();
	stroke(0)
	const len = 5;
	for (let i = 0; i < (width + height) * 10; i++) {
		const x = random(width)
		const y = random(height)
		stroke(255, random(2, 6))
		strokeWeight(random(0.5, 2.5));
		line(x + random(-len), y, x + random(len), y)
		strokeWeight(random(0.5, 2.5));
		line(x, y + random(-4), x, y + random(4))
	}
	pop();
}

class Cell {
	constructor(xi, yi, sze) {
		this.xi = xi;
		this.yi = yi;
		this.scl = 1;
		this.sze = sze;
		this.clr = random(
			// ["#1e212b", "#4d8b31", "#ffc800", "#ff8427", "#ffffff"]
			["#001219", "#005f73", "#0a9396", "#94d2bd", "#e9d8a6", "#ee9b00", "#ca6702", "#bb3e03", "#ae2012", "#9b2226"]
		);
		this.type = floor(random(1, 5));
	}

	show() {
		// only draw existing cells
		if (this.scl < 1) return;

		push()
		// rectMode(CENTER);
		translate(this.xi * this.sze, this.yi * this.sze);
		stroke("white");
		strokeWeight(2);
		fill(this.clr)
		rect(0, 0, this.scl * this.sze, this.scl * this.sze)

		const ctx = drawingContext;
		const n = noise((1 + this.xi * this.yi) * 0.32, this.xi - this.yi + this.scl + this.sze);

		// fill inner gradient
		const s_h = this.sze * this.scl * 0.5;
		const gradient = n < 0.5 ? 
			ctx.createLinearGradient(random(-s_h, s_h), random(-s_h, s_h), 
															 random(s_h, 1-5 * random(-s_h, s_h)), random(s_h, 1-5 * random(-s_h, s_h))) : 
			ctx.createRadialGradient(random(-s_h, 1.5 * s_h), random(-s_h, 1.5 * s_h), random(s_h, 1.5 * s_h), 
															 random(-s_h, 1.5 * s_h), random(-s_h, 1.5 * s_h), random(s_h, 1.5 * s_h));
		gradient.addColorStop(0, lerpColor(color(this.clr), color(0), 0.3));
		gradient.addColorStop(0.5, this.clr);
		gradient.addColorStop(1, lerpColor(color(this.clr), color(255), 0.3));
		ctx.fillStyle = gradient;
		rect(0, 0, this.scl * this.sze, this.scl * this.sze)

		// clip inner drawing
		ctx.save()
		ctx.beginPath();
		ctx.moveTo(0, 0);
		ctx.lineTo(this.scl * this.sze, 0);
		ctx.lineTo(this.scl * this.sze, this.scl * this.sze);
		ctx.lineTo(0, this.scl * this.sze);
		ctx.closePath();
		ctx.clip();

		if (this.type === 1) this.showType1(n);
		if (this.type === 2) this.showType2(n);
		if (this.type === 3) this.showType3(n);
		if (this.type === 4) this.showType4(n);

		ctx.restore()

		noFill();
		rect(0, 0, this.scl * this.sze, this.scl * this.sze)

		pop()
	}

	// arcs with random starting/end angle
	showType1(n) {
		push();
		let clr = lerpColor(color(this.clr), color(0), noise(this.xi, this.yi))
		clr.setAlpha(128);
		stroke(clr)
		noFill();
		translate(this.scl * this.sze * 0.5, this.scl * this.sze * 0.5);
		for (let i = 0; i < this.scl * this.sze * 1.25; i += noise(this.xi, i * 0.1) * this.scl * this.sze * 0.075) {
			// circle(0, 0, i)
			const a1 = noise(this.xi + this.yi, i * 0.12) * TWO_PI
			const a2 = noise(this.yi, i * 0.21) * TWO_PI
			const ni = noise(i * 0.32, this.xi + this.yi)
			strokeWeight(max(0.7, ni * this.scl * this.sze * 0.025));
			arc(ni * this.scl * this.sze * 0.1, fract(ni * 10) * this.scl * this.sze * 0.1, i, i, a1, a2);
		}
		pop();
	}

	// raster of dots
	showType2(n) {
		push();
		// const n = noise(this.xi * this.yi * 0.32, this.xi - this.yi);

		translate(this.scl * this.sze * 0.5, this.scl * this.sze * 0.5);
		rotate((fract(n/PI*100)-0.5) * 0.25)
		translate(-this.scl * this.sze * 0.5, -this.scl * this.sze * 0.5);

		var clr = lerpColor(color(this.clr), n < 0.5 ? color(0) : color(255), noise(this.xi * 0.012, this.yi * 0.021))
		fill(clr)
		noStroke();
		var num = floor(1.5 + fract(n * PI) * 3);
		var sze = this.sze * this.scl;
		for (let y = 0.5; y < num; y++) {
			for (let x = 0.5; x < num; x++) {
				const xo = (noise(fract(n * 2.123) + x * 0.123) - 0.5) * sze / num * 2
				const yo = (noise(fract(n * 4.321) + y * 0.321) - 0.5) * sze / num * 2
				circle(xo + x * sze / num, yo + y * sze / num, sze / num * max(0.1, noise(fract((xo + yo) * 0.345))));
			}
		}
		pop();
	}

	// rotating triangle
	showType3(n) {
		push();

		// const n = noise(this.xi * this.yi * 0.32, (this.xi - this.yi) * this.sze * this.scl);
		var clr = lerpColor(color(this.clr), n < 0.5 ? color(0) : color(255), noise(this.xi * 0.012, this.yi * 0.021))
		fill(clr)
		noStroke();
		var num = floor(2.5 + fract(n * PI) * 8);
		var sze = this.sze * this.scl;
		translate(sze * 0.5, sze * 0.5);
		rotate(n * TWO_PI)

		for (let i = 0; i < num; i++) {
			var xo = (noise(fract(n * 2.123) + this.xi * 0.123 + i) - 0.5) * sze / num * 0.75
			var yo = (noise(fract(n * 4.321) + this.yi * 0.321 + i) - 0.5) * sze / num * 0.75

			const p1 = createVector(noise(fract(n * 0.14434), i) * sze * 2.5, noise(fract(n * 0.4576) + i) * sze * 2.5);
			const p2 = createVector(noise(fract(n * 0.085637), i) * sze * 2.5, noise(fract(n * 0.12145) + i) * sze * 2.5);

			triangle(xo, yo, p1.x, p1.y, p2.x, p2.y);
			rotate(TWO_PI / num)
		}

		pop();
	}

	// n-edges shape
	showType4(n) {
		push();

		// const n = noise(this.xi * this.yi * 0.32, this.xi - this.yi);
		var clr = lerpColor(color(this.clr), n < 0.5 ? color(0) : color(255), noise(this.xi * 0.012, this.yi * 0.021))
		fill(clr)
		noStroke();
		var num = floor(3.5 + fract(n * PI) * 4);
		var sze = this.sze * this.scl;
		translate(sze * 0.5, sze * 0.5);
		rotate(n * TWO_PI)

		beginShape();
		for (let a = 0; a < TWO_PI * 1-(1/(num+1)); a += TWO_PI / num) {
			const radius = (0.5 + sqrt(noise(fract(n * 2.123) + a * 0.123))) * sze * 0.45
			var x = cos(a) * radius;
			var y = sin(a) * radius;
			var xo = (noise(fract(n * 2.123) + this.xi * 0.123) - 0.5) * sze / num * 0.15
			var yo = (noise(fract(n * 4.321) + this.yi * 0.321) - 0.5) * sze / num * 0.15

			vertex(xo + x, yo + y);
			rotate(TWO_PI / num)
		}
		endShape(CLOSE);

		pop();
	}

	// expand cell
	expand(scl, cells, num) {
		// can cell be extended?
		if (scl < 2 || this.scl !== 1 || max(this.xi, this.yi) + scl > num) return false;

		// console.log(`Cell.expand() xi: ${this.xi}, yi: ${this.yi}, scl: ${scl}, num: ${num}`)

		// find inner cells 
		const bi = this.xi + this.yi * num; // base index
		for (let yi = 0; yi < scl; yi++) {
			for (let xi = 0; xi < scl; xi++) {
				const di = xi + yi * num; // delta index
				if (di && cells[bi + di].scl !== 1) {
					return false; // dont change anything
				}
			}
		}

		// all fine, lets change scale and delete joined cells
		this.scl = scl;
		let cR = 0, cG = 0, cB = 0;
		for (let yi = 0; yi < scl; yi++) {
			for (let xi = 0; xi < scl; xi++) {
				var di = xi + yi * num; // delta index
				var c = cells[bi + di];
				if (di) c.scl = 0;
				cR += red(window.color(c.clr));
				cG += green(window.color(c.clr));
				cB += blue(window.color(c.clr));
			}
		}
		cR /= scl * scl;
		cG /= scl * scl;
		cB /= scl * scl;
		// this.clr = color(cR, cG, cB);

		return true;
	}
}
